<script>
  import IsoFigure from "#lib/ui/IsoFigure.svelte";
  import Ping from "#lib/ui/Ping.svelte";
  // The company figure (2026-11-24, founder ask): RogerAI Labs and the RogerAI network on one slab, with Ping,
  // the mascot, as the crew. Left, the lab: a bench, a workstation, a board with a falling training curve, two
  // Pings at work. A Ping in headphones carries a model (a small cube) along the path to the tower and walks
  // back for the next. The tower rings out, and the agents, Pings beside machines people own (a laptop, a
  // workstation, an edge box, a phone), hop and ping back as the ring reaches them. Each Ping is dressed from the
  // iOS app's own wardrobe (PingStyle.swift: heads, bodies, worn things); every eye is the brand red.
  //
  // The drawing between the markers is generated by computer-scientist/article/fig_company_gen.py (the shared
  // camera and hand, isolib.py; Ping's shapes from the iOS rig, PingRig.swift). Runes, no <style> (company.css,
  // lead .pg), no colour literal, every word in HTML, no SVG <text>, role="group" named by its caption. One loop,
  // CSS only; still (reduced motion, print): the crew at rest, the cube in hand, the curve drawn.
  //
  // The crew talks (2026-11-24, founder ask): each Ping has a button over it, hidden until app/pages/company.js
  // runs; a tap and the Ping says one thing about RogerAI. Every line is a claim this site already makes (the
  // cards above, the app page's terminal section, the focus section's heading), in Ping's voice.
  let {
    fig = 1,
    caption = "A model leaves the lab and goes on air. Every agent that hears it answers. Tap a Ping to hear from it.",
    crew = [
      { key: "research", who: "Ping", at: "the original Ping", say: "Hi, I'm Ping. RogerAI is designed in Orange County, California, and our cloud is global." },
      { key: "board", who: "Beanie Ping", at: "Ping in a beanie, at the board", say: "Our results ship with the hardware they ran on, the harness that ran them and the raw outputs, so anyone can rerun them." },
      { key: "probe", who: "Top-hat Ping", at: "Ping in a top hat, at the test mast", say: "Our rule for Wave: the smallest model that can do the job." },
      { key: "carry", who: "Headphones Ping", at: "Ping in headphones, carrying a model", say: "Our models ship in open formats on standard runtimes, so nothing we publish depends on RogerAI continuing to exist." },
      { key: "laptop", who: "Cowboy Ping", at: "Ping in a cowboy hat, at a laptop", say: "roger is one binary, a local harness for local models." },
      { key: "phone", who: "Halo Ping", at: "Ping with a halo, at a phone", say: "The network is OpenAI-compatible, so the client you already use works. There is an iOS app too." },
      { key: "rig", who: "Antenna Ping", at: "Ping with an antenna, at a workstation", say: "The operator keeps physical control of the machine and opens no inbound ports." },
      { key: "edge", who: "Wizard Ping", at: "Ping in a wizard hat, at an edge box", say: "Every job on the network is metered and comes back with a signed receipt." },
    ],
  } = $props();
</script>

